<?php
// Одноразовый установщик ~/kotel-sync.sh (27.11.2026): SSH на хостинге выключен, а заходить в панель — значит
// показать SpaceWeb свой IP. Скрипт приезжает вместе с сайтом из GitHub, вызывает его машина GitHub Actions.
// Ставит только этот, заранее известный скрипт синхронизации; повторный вызов ничего не меняет. Будет удалён из сборки.
header('Content-Type: text/plain; charset=utf-8');
header('X-Robots-Tag: noindex');
$home = dirname(__DIR__, 2);
$target = $home . '/kotel-sync.sh';
$new = base64_decode('');
if (@file_get_contents($target) === $new) { echo "already installed\n"; exit; }
@mkdir($home . '/deployment-backups', 0700, true);
@copy($target, $home . '/deployment-backups/kotel-sync.sh.bak-' . date('Ymd-His'));
if (file_put_contents($target . '.new', $new) !== strlen($new)) { http_response_code(500); echo "write failed\n"; exit; }
chmod($target . '.new', 0755);
if (!rename($target . '.new', $target)) { http_response_code(500); echo "rename failed\n"; exit; }
echo "installed " . strlen($new) . " bytes, sha1 " . sha1($new) . "\n";
